def semver_sort(versions):
    def parse_key(v):
        # strip build metadata
        core_and_pre = v.split('+', 1)[0]
        if '-' in core_and_pre:
            core, pre = core_and_pre.split('-', 1)
            has_pre = 0  # has prerelease sorts first
        else:
            core = core_and_pre
            pre = None
            has_pre = 1  # no prerelease sorts after

        major, minor, patch = (int(x) for x in core.split('.'))

        if pre is not None:
            idents = pre.split('.')
            pre_tuple = []
            for ident in idents:
                if ident.isdigit():
                    pre_tuple.append((0, int(ident), ''))
                else:
                    pre_tuple.append((1, 0, ident))
            pre_tuple = tuple(pre_tuple)
        else:
            pre_tuple = ()

        return (major, minor, patch, has_pre, pre_tuple)

    return sorted(versions, key=parse_key)

